#!/usr/bin/env python3
"""Build the pinned reference as Wasm. No keys are generated by compilation."""
from pathlib import Path
import hashlib,json,os,shutil,subprocess,sys
ROOT=Path(__file__).resolve().parents[1]
SOURCES='hss hss_alloc hss_aux hss_common hss_compute hss_generate hss_keygen hss_param hss_reserve hss_sign hss_sign_inc hss_thread_single hss_verify hss_verify_inc hss_derive hss_zeroize lm_common lm_ots_common lm_ots_sign lm_ots_verify lm_verify endian hash sha256'.split()
def build():
    metadata=json.loads((ROOT/'vendor/UPSTREAM.json').read_text());vendor=ROOT/'vendor/hash-sigs'
    for entry in metadata['files']:
        raw=(vendor/entry['path']).read_bytes()
        assert len(raw)==entry['size'] and hashlib.sha1(b'blob '+str(len(raw)).encode()+b'\0'+raw).hexdigest()==entry['git_blob_sha1']
    compiler_python=os.environ.get('ARDA_ZIG_PYTHON',sys.executable)
    version=subprocess.check_output([compiler_python,'-m','ziglang','version'],text=True).strip()
    if version!='0.14.1':raise ValueError('reviewed_zig_0_14_1_required')
    target=ROOT/'build/wasm-vendor';target.parent.mkdir(exist_ok=True)
    if target.exists():shutil.rmtree(target)
    shutil.copytree(vendor,target)
    header=target/'sha256.h';text=header.read_text();old='#define USE_OPENSSL 1';assert text.count(old)==1
    header.write_text(text.replace(old,'#define USE_OPENSSL 0'))
    out=ROOT/'build/hss-state.wasm'
    exports=['arda_private_ptr','arda_public_ptr','arda_message_ptr','arda_signature_ptr','arda_leaf','arda_clear','arda_generate','arda_sign']
    command=[compiler_python,'-m','ziglang','cc','-target','wasm32-wasi','-mexec-model=reactor','-O2','-I',str(target),
        str(ROOT/'native/hss_state.c'),*[str(target/(s+'.c')) for s in SOURCES],'-Wl,--export-memory',
        '-Wl,--max-memory=67108864','-Wl,--initial-memory=4194304','-Wl,-z,stack-size=1048576',
        *['-Wl,--export='+name for name in exports],'-o',str(out)]
    subprocess.run(command,check=True,timeout=240)
    record=dict(schema='arda.hss.wasm_build.v1',zig_version=version,upstream_tree=metadata['tree_sha'],
        build_copy_patch='sha256.h USE_OPENSSL 1 -> 0; vendor source unchanged',wasm_sha256=hashlib.sha256(out.read_bytes()).hexdigest(),
        wrapper_sha256=hashlib.sha256((ROOT/'native/hss_state.c').read_bytes()).hexdigest(),production_authorized=False)
    (ROOT/'build/hss-state-meta.mjs').write_text('export const WASM_SHA256='+json.dumps(record['wasm_sha256'])+';\n')
    (ROOT/'build/WASM_BUILD.json').write_text(json.dumps(record,indent=2)+'\n');print(json.dumps(record))
if __name__=='__main__':build()
